// v16.xx (topfix1), the HUD spec (2026-10-15, bug B4) and his note "text at top mid is colliding": THE SCORE CAPTION WAS CUT BY THE TOP
// EDGE. In a CAREER or DEMO raid the score block (SCORE, the figure, the clock) hangs its caption 0.8 of the figure above the clock
// line, and the clock line sat 6 above the figure's height, so the caption's baseline landed at about 12 pixels at 1080p and its capitals
// (about 12 high) lost their top. The whole top stack now starts LH(8) lower in those raids, so the caption has its own margin under the
// edge; the compass line, the extraction arrow and the marks under it follow, being laid out from this line.
var _yClk=Math.round(6*_tz+_hClk)+((G&&(G.arcade||G.career))?Math.round(LH(8)*_tz):0);

check:
{v:'VER',what:'the HUD spec (bug B4): the SCORE caption at the top centre of a career raid keeps a margin under the top edge, with all of its capitals on the screen',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||!window.__textTrace||typeof careerPostBuild!=='function') return 'SKIP: no career raid here';
   var bad=[], g, tr, e, i, cap;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     try{ careerPostBuild(g); }catch(_c){}
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={};
     for(i=0;i<3;i++) __frame(0.016);
     tr=__textTrace(function(){ __frame(0.016); });
     for(i=0;i<tr.length;i++) if(tr[i].t==='SCORE'){ e=tr[i]; break; }
     if(!e) return 'SKIP: the score caption was not drawn here';
     cap=e.px*0.78;
     if(e.y-cap<3) bad.push('the SCORE caption (baseline '+Math.round(e.y)+', type '+Math.round(e.px)+') has its capitals within '+Math.round(e.y-cap)+' px of the top edge');
   }catch(e2){ bad.push('threw: '+(e2&&e2.message||e2)); }
   finally{ try{ var g2=__state(); if(g2&&!g2.over){ g2.career=0; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
